<?php
chdir(dirname(__DIR__));

session_start(); require_once 'dbconn.php'; require_once 'includes/functions.php'; requireRole(['School Registrar','System Administrator']);
$msg=''; $err='';
if($_SERVER['REQUEST_METHOD']==='POST') { verifyCsrf(); try {
 $id=(int)($_POST['application_id']??0); $action=$_POST['action']??''; $notes=trim($_POST['registrar_notes']??'');
 $q=$pdo->prepare("SELECT * FROM student_registration_applications WHERE application_id=? AND application_status='For Verification'"); $q->execute([$id]); $a=$q->fetch(); if(!$a) throw new Exception('Application not found or already reviewed.');
 if($action==='reject') { $q=$pdo->prepare("UPDATE student_registration_applications SET application_status='Rejected',registrar_notes=?,reviewed_by=?,reviewed_at=NOW() WHERE application_id=?"); $q->execute([$notes,$_SESSION['user_id'],$id]); $msg='Application rejected.'; }
 elseif($action==='approve') {
  $d=json_decode($a['application_data'],true); if(!is_array($d)) throw new Exception('The submitted registration data is invalid.');
  foreach(['first_name','last_name','birth_date','sex'] as $required) if(empty($d[$required])) throw new Exception('Required application information is missing: '.$required);
  $pdo->beginTransaction();
  $existing=$pdo->prepare('SELECT student_lrn FROM students WHERE student_lrn=? FOR UPDATE'); $existing->execute([$a['student_lrn']]);
  $columns=['psa_birth_certificate_no','last_name','first_name','middle_name','extension_name','birth_date','sex','place_of_birth','religion','mother_tongue','is_ip_member','is_4ps_beneficiary','current_house_no','current_street_sitio','current_barangay','current_municipality','current_province','current_zip_code','permanent_same_as_current','permanent_house_no','permanent_street_sitio','permanent_barangay','permanent_municipality','permanent_province','permanent_zip_code','father_first_name','father_middle_name','father_last_name','father_contact_number','mother_maiden_first_name','mother_maiden_middle_name','mother_maiden_last_name','mother_contact_number','guardian_first_name','guardian_middle_name','guardian_last_name','guardian_contact_number','student_email','student_contact_number','parent_guardian_name','parent_guardian_relationship','parent_guardian_contact','parent_guardian_email','previous_school','last_grade_completed','last_school_year_attended','health_conditions','current_medications','special_medical_concerns','emergency_contact_name','emergency_contact_relationship','emergency_contact_number'];
  $values=[]; foreach($columns as $c) { $v=$d[$c]??null; if($c==='health_conditions') $v=$d['medical_conditions']??null; if(str_starts_with($c,'permanent_') && $c!=='permanent_same_as_current' && !empty($d['permanent_same_as_current'])){$suffix=substr($c,10);$v=$d['current_'.$suffix]??null;} if($c==='parent_guardian_name') $v=$d['parent_name']??null; if($c==='parent_guardian_relationship') $v=$d['parent_relationship']??null; if($c==='parent_guardian_contact') $v=$d['parent_contact']??null; if($c==='parent_guardian_email') $v=$d['parent_email']??null; if(in_array($c,['is_ip_member','is_4ps_beneficiary'],true)) $v=!empty($v)?1:0; if($c==='permanent_same_as_current') $v=array_key_exists($c,$d)?(!empty($d[$c])?1:0):1; $values[]=$v===''?null:$v; }
  if(!$existing->fetch()) { $cols=array_merge(['student_lrn'],$columns); $vals=array_merge([$a['student_lrn']],$values); $sql='INSERT INTO students('.implode(',',$cols).') VALUES('.implode(',',array_fill(0,count($cols),'?')).')'; $pdo->prepare($sql)->execute($vals); }
  else { $sets=[];$updateValues=[];foreach($columns as $i=>$c){$v=$values[$i];if($v!==null && $v!==''){$sets[]="$c=?";$updateValues[]=$v;}}if($sets){$updateValues[]=$a['student_lrn'];$pdo->prepare('UPDATE students SET '.implode(',',$sets).' WHERE student_lrn=?')->execute($updateValues);} }
  $pdo->prepare("UPDATE student_registration_applications SET application_status='Approved',registrar_notes=?,reviewed_by=?,reviewed_at=NOW() WHERE application_id=?")->execute([$notes,$_SESSION['user_id'],$id]);
  $pdo->commit(); $msg='Application approved. Student profile saved. Continue to Enrollment Management.';
 } else throw new Exception('Invalid action.');
 } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); $err=$e instanceof PDOException ? 'Database error: '.($e->errorInfo[2]??$e->getMessage()) : $e->getMessage(); }
}
$search=trim($_GET['lrn']??''); $sql='SELECT * FROM student_registration_applications'; $params=[]; if($search!==''){$sql.=' WHERE student_lrn LIKE ?';$params[]='%'.$search.'%';} $sql.=" ORDER BY FIELD(application_status,'For Verification','Approved','Rejected'),submitted_at DESC"; $q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
require 'includes/header.php'; ?>
<div class="page-heading"><div><h1>Review Parent Registrations</h1></div></div>
<?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?>
<div class="card p-3 mb-3"><form method="get" class="row g-2"><div class="col-md-8"><label class="form-label">Search by LRN</label><input class="form-control" name="lrn" value="<?=e($search)?>" placeholder="Enter full or partial 12-digit LRN"></div><div class="col-auto d-flex align-items-end"><button class="btn btn-primary">Search</button> <a class="btn btn-outline-secondary ms-2" href="../registrar/registration_review.php">Clear</a></div></form></div>
<?php if(!$rows):?><div class="alert alert-info">No registration applications found.</div><?php endif;?>
<?php foreach($rows as $i=>$r):$d=json_decode($r['application_data'],true)?:[];?><div class="card p-3 mb-3"><div class="d-flex justify-content-between flex-wrap"><h5><?=($i+1)?>. <?=e(($d['last_name']??'').', '.($d['first_name']??''))?></h5><span class="badge text-bg-secondary"><?=e($r['application_status'])?></span></div><p class="mb-2"><a class="btn btn-sm btn-outline-primary" href="../registrar/registration_files.php?lrn=<?=urlencode($r['student_lrn'])?>">View / Upload Documents</a></p><p class="small text-muted mb-2">LRN: <strong><?=e($r['student_lrn'])?></strong> · <?=e($r['enrollment_category'])?> · <?=e($r['submitted_at'])?></p><details><summary>View complete submitted information</summary><div class="row g-2 mt-2"><?php foreach($d as $k=>$v):if($v===''||$v===null)continue;?><div class="col-md-4"><small class="text-muted d-block"><?=e(ucwords(str_replace('_',' ',$k)))?></small><?=e(is_array($v)?implode(', ',$v):$v)?></div><?php endforeach;?></div></details><?php if($r['application_status']==='For Verification'):?><form method="post" class="mt-3"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="application_id" value="<?=$r['application_id']?>"><label class="form-label">Registrar Notes</label><textarea class="form-control mb-2" name="registrar_notes" rows="2"><?=e($r['registrar_notes']??'')?></textarea><button class="btn btn-success" name="action" value="approve" onclick="return confirm('Approve this registration?')">Approve & Create Profile</button> <button class="btn btn-outline-danger" name="action" value="reject" onclick="return confirm('Reject this application?')">Reject</button></form><?php elseif($r['registrar_notes']):?><p class="small mt-2 mb-0">Note: <?=e($r['registrar_notes'])?></p><?php endif;?></div><?php endforeach;?><?php require 'includes/footer.php'; ?>
